print('physical sessions info',len(by))
print('field patterns')
pat=collections.Counter()
for base,es in by.items():
 vals_days={x[1] for x in es if x[1] is not None}; vals_sess={x[2] for x in es if x[2] is not None}
 pat[(tuple(sorted(vals_days)),tuple(sorted(vals_sess)))]+=1
print(pat)
for base,es in sorted(by.items()):
 vd={x[1] for x in es if x[1] is not None}; vs={x[2] for x in es if x[2] is not None}
 if len(vd)>1 or len(vs)>1 or (vd and vs and vd!=vs): print('DAY CONFLICT',base,es)
# reward consistency and trial/frame validity collapsed behavior
sessions={}
for p in sorted(glob.glob(root+'/beh/Beh_*.npy')):
 b=np.load(p,allow_pickle=True).item()
 for k,d in b.items():
  base=re.sub(r'_swap[12]$','',k)
  sessions.setdefault(base,d)
 del b;gc.collect()
stat=collections.Counter(); bad=[]
for base,d in sessions.items():
 n=int(d['ntrials']); nr=int(np.sum(d['isRew'])); mode=str(d['Reward_Mode'])
 stat[(mode,nr>0)]+=1
 # trial frame counts after common-length unknown use behavior nfr
 tri=np.asarray(d['ft_trInd']); corr=np.asarray(d['ft_CorrSpc']);
 cnt=np.array([np.sum((tri==i)&corr) for i in range(n)])
 if np.any(cnt==0): bad.append((base,np.where(cnt==0)[0].tolist()))
print('reward mode x any rewarded',stat)
print('zero textured-frame trials using behavior length',len(bad),bad[:20])
# day distribution chosen days then sess, otherwise missing
chosen=[]
for base,es in by.items():
 vals=[x[1] for x in es if x[1] is not None] or [x[2] for x in es if x[2] is not None]
 chosen.append(vals[0] if vals else None)
